// stlport
// Reference lead: Generals Zero Hour RadiusDecalUpdate.cpp. Target rows verify
// create/kill; the BFME 2 decal extension is accounted for by the shared view.

#include "RadiusDecalUpdateView.h"

void RadiusDecalUpdate::createRadiusDecal(const RadiusDecalTemplate &radiusDecalTemplate, float radius, const Coord3D &pos)
{
	m_deliveryDecal.clear();
	radiusDecalTemplate.createRadiusDecal(pos, radius, getObject()->getControllingPlayer(), m_deliveryDecal);
	setWakeFrame(getObject(), (UpdateSleepTime)(m_deliveryDecal.m_empty ? 0x3FFFFFFF : 1));
}

// ?killRadiusDecal@RadiusDecalUpdate@@QAEXXZ
void RadiusDecalUpdate::killRadiusDecal()
{
	m_deliveryDecal.clear();
	setWakeFrame(getObject(), (UpdateSleepTime)0x3FFFFFFF);	// UPDATE_SLEEP_FOREVER
}
